    public List<TwinTemplate> testGetAll() throws Throwable {
    LOGGER.info( "TwinTemplateTest:testGetAll() - Retrieving Collection of TwinTemplates:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all TwinTemplate : " );
    List<TwinTemplate> collection  = null;

    try {
        // call the static get method on the TwinTemplateService
        collection = service.getAllTwinTemplate();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            TwinTemplate currEntity  = null;
            Iterator<TwinTemplate> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getTwinTemplateId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

